CREATE POLICY "UPDATE" ON "public"."invoiceSettlement" FOR UPDATE USING (((("paymentId" IS NULL OR EXISTS (SELECT 1 FROM "public"."payment" p WHERE "p"."id" = "invoiceSettlement"."paymentId" AND "p"."companyId" = "invoiceSettlement"."companyId" AND "status" = 'Draft')) AND ("memoId" IS NULL OR EXISTS (SELECT 1 FROM "public"."memo" p WHERE "p"."id" = "invoiceSettlement"."memoId" AND "p"."companyId" = "invoiceSettlement"."companyId" AND "status" = 'Draft'))) AND "companyId" = ANY ((SELECT get_companies_with_employee_permission('invoicing.payments_update'))::text[])));
CREATE POLICY "DELETE" ON "public"."invoiceSettlement" FOR DELETE USING (((("paymentId" IS NULL OR EXISTS (SELECT 1 FROM "public"."payment" p WHERE "p"."id" = "invoiceSettlement"."paymentId" AND "p"."companyId" = "invoiceSettlement"."companyId" AND "status" = 'Draft')) AND ("memoId" IS NULL OR EXISTS (SELECT 1 FROM "public"."memo" p WHERE "p"."id" = "invoiceSettlement"."memoId" AND "p"."companyId" = "invoiceSettlement"."companyId" AND "status" = 'Draft'))) AND "companyId" = ANY ((SELECT get_companies_with_employee_permission('invoicing.payments_delete'))::text[])));

-- item
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'item' LOOP
