-- user
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'user' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'user');
  END LOOP;
END
$authz$;
ALTER TABLE public."user" ENABLE ROW LEVEL SECURITY;

    CREATE POLICY "Employees can view users with an account in their company" ON "public"."user" AS PERMISSIVE FOR SELECT TO public USING (((id IN ( SELECT employee.id
   FROM employee
  WHERE (employee."companyId" = ANY (( SELECT get_companies_with_employee_role() AS get_companies_with_employee_role)::text[])))) OR (id IN ( SELECT "customerAccount".id
   FROM "customerAccount"
  WHERE ("customerAccount"."companyId" = ANY (( SELECT get_companies_with_employee_role() AS get_companies_with_employee_role)::text[])))) OR (id IN ( SELECT "supplierAccount".id
   FROM "supplierAccount"
  WHERE ("supplierAccount"."companyId" = ANY (( SELECT get_companies_with_employee_role() AS get_companies_with_employee_role)::text[]))))));
    CREATE POLICY "Employees with Accounts Edit can update users in their company" ON "public"."user" AS PERMISSIVE FOR UPDATE TO public USING ((id IN ( SELECT "userToCompany"."userId"
   FROM "userToCompany"
  WHERE ("userToCompany"."companyId" = ANY (( SELECT get_companies_with_employee_permission('users.accounts_update'::text) AS get_companies_with_employee_permission)::text[]))))) WITH CHECK ((id IN ( SELECT "userToCompany"."userId"
   FROM "userToCompany"
  WHERE ("userToCompany"."companyId" = ANY (( SELECT get_companies_with_employee_permission('users.accounts_update'::text) AS get_companies_with_employee_permission)::text[])))));
    CREATE POLICY "Requests with an API key can select users from their company" ON "public"."user" AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM "userToCompany"
  WHERE (("userToCompany"."userId" = "user".id) AND ("userToCompany"."companyId" = get_company_id_from_api_key())))));
    CREATE POLICY "Users can modify themselves" ON "public"."user" AS PERMISSIVE FOR UPDATE TO public USING (((( SELECT auth.uid() AS uid))::text = id)) WITH CHECK (((( SELECT auth.uid() AS uid))::text = id));
    CREATE POLICY "Users can view other users from their same company" ON "public"."user" AS PERMISSIVE FOR SELECT TO public USING (((id = (( SELECT auth.uid() AS uid))::text) OR (id IN ( SELECT "userToCompany"."userId"
   FROM "userToCompany"
  WHERE ("userToCompany"."companyId" IN ( SELECT "userToCompany_1"."companyId"
           FROM "userToCompany" "userToCompany_1"
          WHERE ("userToCompany_1"."userId" = (( SELECT auth.uid() AS uid))::text)))))));
  

